const clampPercent = (value: number) => {
  if (!Number.isFinite(value)) return 0;
  return Math.min(100, Math.max(0, Math.round(value)));
};

export const widthPercentClass = (value: number) => WIDTH_PERCENT_CLASSES[clampPercent(value)];
export const leftPercentClass = (value: number) => LEFT_PERCENT_CLASSES[clampPercent(value)];
